insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_music4_v1'
from (values
('117.313.c.1.A',4,'A senior streams two conductors'' recordings of the same symphony and attends a live performance, then writes which interpretation best honors the score. She is doing what?','["Evaluating exemplary musical examples across media", "Scheduling rehearsals", "Editing a program", "Selling merchandise"]'::jsonb,0,'Evaluation weighs interpretive choices.','original'),
('117.313.c.1.A',4,'Which comment shows an evaluation of a live performance?','["The stage was wide", "The woodwinds'' unified attacks gave the finale real clarity", "The hall opened at six", "Tickets were sold out"]'::jsonb,1,'Evaluation addresses musical qualities.','original'),
('117.313.c.1.B',4,'A fugue in which voices enter one after another with the same subject displays which advanced texture?','["Block homophony", "Monophony", "Imitative polyphony", "Unison"]'::jsonb,2,'Fugal entries are imitative and polyphonic.','original'),
('117.313.c.1.B',4,'Heterophony occurs when performers do what?','["Sing one note only", "Play in strict canon", "Remain silent", "Play slightly varied versions of the same melody at the same time"]'::jsonb,3,'Heterophony is simultaneous variation of one melody.','original'),
('117.313.c.1.C',4,'A dominant seventh chord built on G contains which pitches?','["G, B, D and F", "G, C, E and B", "G, B-flat, D and F", "G, B, D and F-sharp"]'::jsonb,0,'A dominant seventh has a major triad and a minor seventh.','original'),
('117.313.c.1.C',4,'An inverted chord is one in which what is true?','["All notes are doubled", "A note other than the root is in the bass", "The chord has no third", "The key changes"]'::jsonb,1,'Inversion changes the lowest note.','original'),
('117.313.c.1.D',4,'A passage shifts between 3/4 and 6/8 so that the measure length stays similar but the feel changes. This technique is called what?','["Rubato", "Fermata", "Hemiola", "Crescendo"]'::jsonb,2,'Hemiola shifts between two-feel and three-feel groupings.','original'),
('117.313.c.1.D',4,'Analyzing a polyrhythm means studying what?','["A silent measure", "A key change", "A single pitch", "Two or more contrasting rhythms sounding together"]'::jsonb,3,'Polyrhythm layers rhythms.','original'),
('117.313.c.1.E',4,'A theme and variations piece develops its ideas by doing what?','["Restating the theme with changing treatments", "Never repeating the theme", "Using only rests", "Deleting melody"]'::jsonb,0,'Variations alter a recurring theme.','original'),
('117.313.c.1.E',4,'In sonata-allegro form, the section that presents the main themes is called the ___.','["Coda only", "Exposition", "Trio", "Refrain"]'::jsonb,1,'The exposition introduces themes.','original'),
('117.313.c.1.F',4,'An ensemble tunes its chord so the root, third and fifth are balanced, and the voices sound as one. Which two concepts are being analyzed?','["Tempo and key", "Form and texture", "Balance and blend", "Meter and clef"]'::jsonb,2,'Balance is volume; blend is tone unity.','original'),
('117.313.c.1.F',4,'Poor blend in a choir is often caused by what?','["Matching vowels", "Standing together", "Listening closely", "Singers using widely different vowel shapes and vibrato"]'::jsonb,3,'Mismatched tone qualities hurt blend.','original'),
('117.313.c.1.G',4,'A choral work from the Renaissance with sacred Latin text and imitative polyphony is a ___.','["Motet", "Opera aria", "Zydeco tune", "Hip-hop track"]'::jsonb,0,'Motets are sacred polyphonic works.','original'),
('117.313.c.1.G',4,'Which genre is most associated with sectional large-scale orchestral works in several movements?','["Lullaby", "Symphony", "Work chant", "Jingle"]'::jsonb,1,'A symphony is a multi-movement orchestral piece.','original'),
('117.313.c.1.H',4,'Analyzing how a composer uses dissonance resolving to consonance addresses which element?','["Timbre only", "Meter", "Harmony", "Tempo only"]'::jsonb,2,'Resolution is a harmonic process.','original'),
('117.313.c.1.H',4,'Expression in music is shaped by which of these?','["Ticket pricing", "Seat locations", "Program covers", "Dynamics, articulation and tempo choices"]'::jsonb,3,'These elements create expression.','original'),
('117.313.c.1.I',3,'A musician with a sore wrist should do what first?','["Stop playing and consult a qualified health professional if pain persists", "Ignore it", "Practice longer", "Push through at full volume"]'::jsonb,0,'Early care prevents injury.','original'),
('117.313.c.1.I',3,'Which routine best applies wellness to a long practice day?','["Only coffee", "Breaks, hydration, stretching and varied tasks", "Constant repetition of one passage", "No breaks"]'::jsonb,1,'A varied, restful routine protects the body.','original'),
('117.313.c.2.A',4,'A student notates a melody with triplets across the bar line and a tied note into the next measure. What must the notation show?','["Only tempo", "Only lyrics", "Accurate durations and pitch with ties", "Only pitch names"]'::jsonb,2,'Advanced notation records rhythm precisely.','original'),
('117.313.c.2.A',4,'When writing a melody in compound meter, how should eighth notes in 6/8 usually be beamed?','["In groups of five", "In groups of seven", "Never beamed", "In two groups of three"]'::jsonb,3,'Beaming shows the compound beat.','original'),
('117.313.c.2.B',4,'The term rubato directs a performer to do what?','["Flex the tempo expressively", "Play at a rigid beat", "Stop playing", "Play only loudly"]'::jsonb,0,'Rubato allows tempo freedom.','original'),
('117.313.c.2.B',4,'The expression sostenuto asks for what?','["Very short notes", "Sustained, smooth playing", "Silence", "Rapid repetition"]'::jsonb,1,'Sostenuto means sustained.','original'),
('117.313.c.3.A',4,'A tenor adapts his tone from bright for a musical-theatre piece to a darker, rounder sound for a sacred work. This shows what?','["Lack of practice", "Weak support", "Genre-appropriate characteristic sound", "Inconsistent technique"]'::jsonb,2,'Tone adapts to the style.','original'),
('117.313.c.3.A',4,'Which approach best develops mature tone on a brass instrument?','["Short blasts", "Pinched lips", "Shallow breaths", "Long tones with a steady airstream and open throat"]'::jsonb,3,'Long tones build control.','original'),
('117.313.c.3.B',4,'A pianist analyzes how arm weight and wrist freedom affect her sound and reduces tension. She is doing what?','["Applying psychomotor and kinesthetic analysis to technique", "Selling tickets", "Writing programs", "Moving a piano"]'::jsonb,0,'Physical analysis improves technique.','original'),
('117.313.c.3.B',4,'A singer feels her breath gets shallow on high phrases. What is the best adjustment?','["Clench the jaw", "Re-engage low breath support and keep the ribs expanded", "Lift the shoulders", "Hold the breath"]'::jsonb,1,'Support remains steady on high notes.','original'),
('117.313.c.3.C',4,'Playing a passage of mixed triplets and sixteenth notes at tempo requires what?','["Ignoring the beat", "Playing all notes equal", "Precise subdivision and steady pulse", "Random guessing"]'::jsonb,2,'Complex rhythms require accuracy.','original'),
('117.313.c.3.C',4,'To master a difficult rhythm, a student should first do what?','["Skip the measure", "Remove the rests", "Play it at full speed immediately", "Practice slowly with a metronome and increase gradually"]'::jsonb,3,'Gradual practice builds accuracy.','original'),
('117.313.c.3.D',4,'A piece in F-sharp minor has how many sharps in its key signature?','["Three", "Six", "Two", "Zero"]'::jsonb,0,'F-sharp minor shares A major''s three sharps.','original'),
('117.313.c.3.D',4,'A modulation to the dominant key adds what to the key signature of a major piece, in general?','["Nothing at all ever", "One more sharp or one fewer flat", "No change", "Three flats"]'::jsonb,1,'Moving to the dominant adds a sharp.','original'),
('117.313.c.3.E',4,'Just intonation adjusts a major third to be slightly lower than equal temperament so the chord rings. Why?','["To change the key", "To make it louder", "To make the chord resonate purely", "To lengthen the note"]'::jsonb,2,'Pure intervals reduce beating.','original'),
('117.313.c.3.E',4,'A conductor asks for a long-arching phrase that peaks in measure six. What does she want?','["No dynamics", "A frozen tempo", "Equal volume on each note", "Direction in the phrase with a planned climax"]'::jsonb,3,'Phrasing builds to a high point.','original'),
('117.313.c.3.F',4,'A student writes a four-part arrangement for her ensemble with increasingly demanding rhythms. She is doing what?','["Creating music at an increasing level of difficulty", "Copying a piece", "Buying instruments", "Avoiding notation"]'::jsonb,0,'Compositions grow in complexity.','original'),
('117.313.c.3.F',4,'Which tool allows a composer to hear a notated draft before the ensemble rehearses it?','["A thermometer", "Notation software with playback", "A coupon", "A calendar"]'::jsonb,1,'Playback supports revision.','original'),
('117.313.c.4.A',4,'A hornist sight reads a piece in a new style and still produces a centered, appropriate sound. This shows what?','["Memorization", "Poor control", "Mature tone while sight reading", "Surprise"]'::jsonb,2,'Tone stays consistent.','original'),
('117.313.c.4.A',4,'What most helps a sight reader preserve tone quality at tempo?','["Shallow breath", "Stopping often", "Tension", "Steady air and relaxed technique"]'::jsonb,3,'Relaxed breath supports tone.','original'),
('117.313.c.4.B',4,'A sight-reading violist scans ahead for position shifts and plans her bow distribution. She is refining what?','["Psychomotor and kinesthetic application", "Lighting", "Concert attire", "Parking"]'::jsonb,0,'Planning supports physical execution.','original'),
('117.313.c.4.B',4,'Why should a sight reader keep a loose grip and open posture?','["To play softer always", "To maintain tone and avoid strain", "To avoid reading", "To look relaxed only"]'::jsonb,1,'Relaxed technique prevents tension.','original'),
('117.313.c.4.C',4,'A sight reader finds a measure with sixteenth-note groupings and slurred pairs. What should she prioritize?','["Skipping the slurs", "Speeding up", "Correct articulation and steady subdivisions", "Ignoring accents"]'::jsonb,2,'Articulation and rhythm both matter.','original'),
('117.313.c.4.C',4,'Which method keeps a sight reader in time during a change of meter?','["Guessing", "Ignoring the bar lines", "Stopping at the change", "Counting the new pattern aloud with a steady subdivision"]'::jsonb,3,'Counting keeps pulse.','original'),
('117.313.c.4.D',4,'A sight-reading piece modulates up a whole step in the middle section. What should the reader check?','["New key signature or accidentals", "Only the clef", "Nothing", "Only the title"]'::jsonb,0,'Modulations alter pitches.','original'),
('117.313.c.4.D',4,'When a piece shifts between Dorian and Aeolian mode, which note usually changes?','["The octave", "The sixth scale degree", "The fifth", "The root"]'::jsonb,1,'Dorian has a raised sixth.','original'),
('117.313.c.4.E',4,'A singer reading an unfamiliar line uses movable do to label scale degrees. What is that tool?','["A tempo", "A rhythm syllable", "A melodic reading system", "A bowing pattern"]'::jsonb,2,'Movable do is a pitch system.','original'),
('117.313.c.4.E',4,'Which method helps an instrumentalist read pitches in a new key?','["Guessing", "Ignoring the key", "Playing randomly", "Labeling note names or scale degrees mentally"]'::jsonb,3,'Systems aid reading.','original'),
('117.313.c.4.F',4,'A sight reader sees a forte-piano marking followed by a swell. How should she respond?','["Start loud, drop to soft, then grow", "Skip it", "Play only soft", "Play uniformly"]'::jsonb,0,'Dynamic markings shape the passage.','original'),
('117.313.c.4.F',4,'What is the benefit of identifying phrase peaks before sight reading?','["It lowers the tempo", "It helps shape the line musically", "It changes the key", "It removes rests"]'::jsonb,1,'Phrase awareness improves musicality.','original'),
('117.313.c.4.G',4,'An alto matches her vowel to the sopranos'' open ''ah'' on a held chord and tunes the third. She is working on what?','["Notation", "Fingering", "Accurate intonation in sight reading", "Bowing"]'::jsonb,2,'Vowel unity improves tuning.','original'),
('117.313.c.4.G',4,'Why do ensembles tune the third of a chord lower in just intonation?','["To change tempo", "To speed up", "To play louder", "To reduce beating and ring more purely"]'::jsonb,3,'Pure thirds blend better.','original'),
('117.313.c.5.A',4,'A student hears a piece with ostinato, modal harmonies and a gamelan-like texture and identifies its cultural origin. She is doing what?','["Discriminating music by culture and style", "Naming costumes", "Reading tickets", "Counting beats"]'::jsonb,0,'Discrimination uses stylistic cues.','original'),
('117.313.c.5.A',4,'Which feature would help distinguish Classical period music from Romantic?','["Cover art", "Balanced phrases and clear forms versus expansive expression", "Instrument price", "Concert length only"]'::jsonb,1,'Style traits differ by period.','original'),
('117.313.c.5.B',4,'A student evaluates how protest songs influenced a social movement. She is evaluating what?','["A rest pattern", "A key change", "The relevance of music to society", "A tuning chart"]'::jsonb,2,'Music reflects and shapes culture.','original'),
('117.313.c.5.B',4,'Why do many cultures use music in rites of passage?','["It replaces language", "It prevents change", "It avoids ceremony", "It marks transitions and expresses shared values"]'::jsonb,3,'Music accompanies important moments.','original'),
('117.313.c.5.C',4,'Using ratios to explain why an octave sounds consonant connects music with which subject?','["Mathematics", "Dance only", "Typing", "Cooking"]'::jsonb,0,'Frequency ratios are mathematical.','original'),
('117.313.c.5.C',4,'Setting a poem''s meter to rhythm connects music with which discipline?','["Carpentry", "English language arts", "Physics only", "Welding"]'::jsonb,1,'Poetic meter links to musical rhythm.','original'),
('117.313.c.5.D',4,'A music therapist uses songs to support patients'' communication. Which career field is this?','["Lifeguarding", "Surveying", "Music therapy", "Plumbing"]'::jsonb,2,'Music therapy is a music-related career.','original'),
('117.313.c.5.D',4,'Explaining a music career includes describing what?','["Lunch menus", "The musician''s favorite color", "Parking details", "Typical duties, training and work settings"]'::jsonb,3,'Careers are explained by duties and training.','original'),
('117.313.c.5.E',4,'Evaluating how AI-generated music affects composers addresses which area?','["Technological, ethical and economic impact", "Key only", "Seating only", "Tempo only"]'::jsonb,0,'AI raises several issues for musicians.','original'),
('117.313.c.5.E',4,'Why is crediting composers and performers important?','["It removes copyright", "It respects creators and supports their livelihoods", "It changes the key", "It lengthens a piece"]'::jsonb,1,'Credit is ethical and economic.','original'),
('117.313.c.5.F',4,'A senior builds a curriculum vitae and audition video for conservatory applications. What is she generating?','["A mode", "A tuning fork", "Tools for college and career preparation", "A time signature"]'::jsonb,2,'These materials support applications.','original'),
('117.313.c.5.F',4,'Which item is typical of an electronic music portfolio?','["Calendars of holidays", "Bus maps", "Menus", "Recordings, repertoire list and teacher references"]'::jsonb,3,'Portfolios document skills and references.','original'),
('117.313.c.6.A',3,'During a recorded performance review, the best audience behavior is what?','["Listening attentively and respecting the performers'' work", "Mocking it", "Leaving during it", "Talking over it"]'::jsonb,0,'Respect applies to recordings too.','original'),
('117.313.c.6.A',3,'A performer who handles a mistake onstage with composure is showing what?','["Rudeness", "Professional concert etiquette", "Poor preparation", "Disinterest"]'::jsonb,1,'Composure is professional.','original'),
('117.313.c.6.B',4,'A rubric for evaluating a mariachi ensemble differs from one for a madrigal group because each style prizes what?','["Silence", "The same exact sound", "Different tone, rhythm and stylistic features", "Identical costumes"]'::jsonb,2,'Styles have different standards.','original'),
('117.313.c.6.B',4,'Which is the best criterion for evaluating a choral performance?','["Brightness of lights", "Row of seats", "Ticket price", "Intonation, blend, diction and expression"]'::jsonb,3,'These are musical criteria.','original'),
('117.313.c.6.C',4,'A peer''s feedback names a specific measure and suggests a new bowing. What type of feedback is this?','["Constructive and specific", "Vague", "Hurtful", "Irrelevant"]'::jsonb,0,'Specific suggestions help improvement.','original'),
('117.313.c.6.C',4,'Feedback can be shared in which formats?','["Only silence", "Written comments, recordings or conferences", "Only rumors", "Only gossip"]'::jsonb,1,'Several formats are valid.','original'),
('117.313.c.6.D',4,'A musician logs each rehearsal''s goals, listens to recordings and adjusts her plan weekly. She is developing what?','["A concert flyer", "A seating chart", "A process for self-evaluation", "A ticket booth"]'::jsonb,2,'Reflection and logs drive growth.','original'),
('117.313.c.6.D',4,'Which tool best supports personal artistic improvement?','["Coupons", "Parking passes", "Posters", "Recorded self-assessments tied to specific goals"]'::jsonb,3,'Tools tied to goals show progress.','original'),
('117.313.c.6.E',4,'A composer compares her new piece with a model work and notes how the model develops its motif more fully. She is doing what?','["Evaluating a composition by comparing it to an exemplary model", "Cancelling the piece", "Ignoring the model", "Copying the model note for note"]'::jsonb,0,'Comparison guides revision.','original'),
('117.313.c.6.E',4,'After evaluating a performance against a model, which recommendation is most useful?','["It was bad", "Adjust the balance in measures 12 to 16 so the melody leads", "Whatever you like", "Try harder"]'::jsonb,1,'Specific recommendations are actionable.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
